// Single entry point for syntax highlighting across the UI (diffs, approvals,
// markdown code fences). Returns the input unchanged on empty/illegal input so
// callers never have to guard.
export function highlightCode(code: string, language: string): string {
  const lang = resolveLanguage(language);
  if (!code.trim() || chalk.level === 0 || lang === 'plaintext') return code;
  try {
    const result = hljs.highlight(code, { language: lang, ignoreIllegals: true });
    // A scan that fails does not throw: highlight.js returns the HTML-escaped source in `value`
    // instead of the emitter's output, so hand back the source rather than its escapes.
    return result.illegal || result.errorRaised ? code : result.value;
  } catch {
    return code;
  }
}

// Tokenize once and return a list of styled spans (text + paint function) per
// display row.  The emitter keeps grammar state across rows so multi-line
// constructs (block comments, template literals, heredocs) retain their scope
// on continuation rows — callers split the result back into rows themselves.
// Returns the input unchanged on empty/illegal input so callers never have to
// guard.
export type Span = { text: string; paint: Paint };
export function highlightCodePerRow(code: string, language: string): Span[][] {
  const lang = resolveLanguage(language);
  if (!code.trim() || chalk.level === 0 || lang === 'plaintext')
    return code.split('\n').map(line => [{ text: line, paint: (t: string) => t }]);
  try {
    const result = hljs.highlight(code, { language: lang, ignoreIllegals: true });
    if (result.illegal || result.errorRaised)
      return code.split('\n').map(line => [{ text: line, paint: (t: string) => t }]);
    // Reconstruct the token stream from the ScopeNode tree, then split into rows.
    const spans: Span[] = [];
    const theme = codeTheme();
    paintTree({ scope: undefined, children: [] }, theme);

    function paintTree(node: ScopeNode, theme: Record<string, Paint>): void {
      for (const child of node.children) {
        if (typeof child === 'string') {
          spans.push({ text: child, paint: theme[node.scope || 'default'] || ((t: string) => t) });
        } else {
          paintTree(child, theme);
        }
      }
    }

    // Rebuild from result.value: highlight.js returns HTML-escaped text with
