**Section 2: Lines 334-414 (PlainChangeLine and padToWidth)**

```typescript
// Dark backgrounds — readable on dark terminals (the syntax palette over a red/green tint).
// Saturation is where these read as red and green rather than as a dull tint (#331); luminance is
// what the pastel foreground needs, so it is held where the previous values had it. The floor is
// the GRAY comment color on the green line, at ~2.2:1 — it recedes, but it stays readable; the
// green string and rose variable colors that sit on the same-hue tints stay above 3:1. GitHub's
// dark-theme tints composite duller than the values these replaced, so they were not the reference.
const REMOVED_BG = '#6b1a22';
const ADDED_BG = '#0f5a2c';
const ROW_BG: Record<Side, string> = { added: ADDED_BG, removed: REMOVED_BG };
// Brighter variants for the intra-line word-level highlight, so changed words stand out from the
// line's base background. The changed word is painted in one fixed foreground, not in syntax
// colors, so only that one contrast binds here.
const REMOVED_HIGHLIGHT_BG = '#a3303a';
const ADDED_HIGHLIGHT_BG = '#1f8a48';
// The changed word's foreground. Not bold, and not the terminal's default: the brighter tint
// already marks the span, and bold on top of it read as glare; the default fg is whatever the
// terminal theme picked, which on a pure-white theme is that same glare. Half a step below white
// — 3.6:1 on the green highlight, 5.6:1 on the red — so the word still reads as the brightest
// thing on the row without shouting.
const HIGHLIGHT_FG = '#e8e8e8';

function PlainChangeLine({
  line,
  side,
  language,
  maxWidth,
  gutter,
}: {
  line: string;
  side: 'removed' | 'added';
  language: string;
  maxWidth: number;
  gutter: string;
}) {
  const prefix = side === 'added' ? '+ ' : '- ';
  return (
    <WrappedRow
      content={highlightCode(line, language)}
      prefix={prefix}
      gutter={gutter}
      maxWidth={maxWidth}
      side={side}
    />
  );
}

// Pad with trailing spaces so the line bg spans the full available width even
// for short or empty lines. Returns no padding if content already exceeds width.
//
// Measured in COLUMNS, not characters: a CJK glyph or an emoji in a changed line is two columns
// wide, so counting characters overshot the padding and pushed the background past the edge — the
// same misalignment tabs used to cause, from the other direction.
//
// And measured as the TERMINAL draws them, not as string-width reports them (`drawnWidth`), which
// is the same direction again: `✔`, `⚠`, `⏺` and the rest of the text-presentation pictographs
// spend two columns to Ink and one on the screen, so padding by the measurement left the tint a
// column short per glyph — the block's right edge stepped in on exactly the rows carrying a check
// mark. A row that draws its full width then MEASURES wider than it draws, which is why WrappedRow
// hands the row box that ink width as slack (#439).
function padToWidth(text: string, maxWidth: number): string {
  const visible = drawnWidth(text);
  return visible < maxWidth ? ' '.repeat(maxWidth - visible) : '';
}
